public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(this.FromHours < 0)
        ret = checkFailed(strFmt("%1 must be greater than or equal to 0", fieldPName(NVHcmWorkerFlightRangeSetup, FromHours)));

    if(this.ToHours < 0)
        ret = checkFailed(strFmt("%1 must be greater than or equal to 0", fieldPName(NVHcmWorkerFlightRangeSetup, ToHours)));

    if(this.AdditionalLeaves < 0)
        ret = checkFailed(strFmt("%1 must be greater than or equal to 0", fieldPName(NVHcmWorkerFlightRangeSetup, ToHours)));

    if(this.FromHours > this.ToHours)
        ret = checkFailed(strFmt("%1 must be greater or equal to %2.", fieldPName(NVHcmWorkerFlightRangeSetup, FromHours), fieldPName(NVHcmWorkerFlightRangeSetup, ToHours)));

    ret = this.validateRangeOverlap();

    return ret;
}

private boolean validateRangeOverlap()
{
    NVHcmWorkerFlightRangeSetup otherFlightRangeSetup;

    while select otherFlightRangeSetup
        where otherFlightRangeSetup.RecId   != this.RecId
            && (this.FromHours              <= otherFlightRangeSetup.ToHours && this.ToHours >= otherFlightRangeSetup.FromHours)
    {
        return checkFailed("Hours range are overlapping with other record. This must be unique to proceed.");
    }

    return true;
}

public static NVHcmWorkerFlightRangeSetup find(Hours _hours)
{
    NVHcmWorkerFlightRangeSetup flightRangeSetup;

    select firstonly flightRangeSetup
        where flightRangeSetup.FromHours    <= _hours
            && flightRangeSetup.ToHours     >= _hours;

    return flightRangeSetup;
}
